/* ═══════════════════════════════════════════════════════════════════════
   BLANK-SLATE TOOL FILE — images.grunge.js — Grunge overlay for images.

   THIS FILE IS AN OPERATE-SUBFAMILY of the images family (same shape as
   images.filters): it acts on EXISTING images, so its UI lives on the
   right-click-an-image menu ("Grunge…"), never in the Add Images menus.
   It owns no object type — it decorates rendering and export through the
   onObjectRender / onAfterObjectExport hooks. Delete this file and images
   simply render clean; the grunge data on objects survives untouched.

   WHY ITS OWN FIELD AND NOT obj.filters
   images.filters sanitizes obj.filters on load and hard-drops any entry
   whose type isn't blur/grain/fade. A 'grunge' entry pushed into that
   array is therefore deleted every time a project opens — whichever tool
   runs first, the strip wins. So this tool keeps its data on its own
   namespaced field (obj.grunge) and leaves obj.filters entirely alone,
   per AGENTS.md rule 8. The two tools stack cleanly: filters recolour the
   pixels, grunge lays dirt on top of the result.

   LOAD ORDER MATTERS (mildly): 'images.grunge' sorts after
   'images.filters', so our export hook runs after theirs and the grunge
   lands on top of their repaint. Keep the filename as-is.

   DATA: obj.grunge = { amount: 0..100, texture: 'dust'|'concrete'|'splatter' }
   The slider is BIPOLAR like fade — 50 is neutral and drops the field
   entirely. Below 50 the texture is INVERTED and screened (white dust and
   scratches added); above 50 it is multiplied as-is (black dirt added).
   Blend strength = |amount-50|/50, applied as layer opacity.
   Inversion on the screen side is deliberate: these plates are ~85% white
   by area, so screening them un-inverted just floods the image to white.

   DISPLAY uses an overlay <div> with mix-blend-mode (a texture composite
   can't be expressed as a CSS filter on the <img>), isolated to the object
   so it never blends into the canvas behind it, and masked by the image's
   own alpha so cut-outs stay clean. EXPORT repaints the same overlay
   through canvas globalCompositeOperation 'screen'/'multiply' with the
   identical cover-fit maths, so what you see is what you get.

   THE THREE INVARIANTS
   - ctx.pushUndo()      BEFORE mutating any object
   - ctx.renderObjects() AFTER adding/removing/restructuring objects
   - ctx.markDirty()     AFTER any change (schedules the auto-save)
   ONLY TOUCH ctx — the full API is in AGENTS.md.

   To remix (more plates, different blends): copy to
   images.grunge.<yourname>.js, set basedOn: 'images.grunge', append your
   name to authors, and add entries to the TEXTURES table.
   ═══════════════════════════════════════════════════════════════════════ */

// ── MANIFEST ────────────────────────────────────────────────────────────
export const manifest = {
  id: 'images.grunge',
  name: 'Grunge',
  version: '1.0.0',
  authors: ['Forma Rosa Creative', 'santibraby'],
  basedOn: 'images',
  description: 'Dirty grunge plates on images — screen on the left, multiply on the right.',
};

// ── REGISTER ────────────────────────────────────────────────────────────
export function register(ctx) {
  const NEUTRAL = 50;

  // Embedded grunge plates (grayscale JPEG, 1100px, base64 — the tool has
  // to survive being pasted into a chat window, so no external assets).
  const TEXTURES = [
    { id: 'dust',     label: 'Dust',     w: 1100,     h: 733,     url: 'data:image/jpeg;base64,',     thumb: 'data:image/jpeg;base64,' },
    { id: 'concrete', label: 'Concrete', w: 1100, h: 733, url: 'data:image/jpeg;base64,', thumb: 'data:image/jpeg;base64,' },
    { id: 'splatter', label: 'Splatter', w: 1100, h: 733, url: 'data:image/jpeg;base64,', thumb: 'data:image/jpeg;base64,' },
  ];
  const TEX_BY_ID = {};
  for (const t of TEXTURES) TEX_BY_ID[t.id] = t;
  const DEFAULT_TEX = 'dust';

  // Decoded copies for the export path (display uses CSS url()).
  const texImg = {};
  for (const t of TEXTURES) {
    const im = new Image();
    im.src = t.url;
    texImg[t.id] = im;
  }

  // Remembers the last plate you picked so choosing one while the slider
  // still sits at neutral (nothing stored yet) isn't forgotten.
  let lastTexture = DEFAULT_TEX;

  // ── DATA ──────────────────────────────────────────────────────────────
  function grAmount(o) {
    const a = o && o.grunge ? Number(o.grunge.amount) : NaN;
    return isFinite(a) ? Math.max(0, Math.min(100, a)) : NEUTRAL;
  }
  function grTexture(o) {
    const t = o && o.grunge ? o.grunge.texture : null;
    return TEX_BY_ID[t] ? t : lastTexture;
  }
  // Normalized read; null means "no visible grunge".
  function gr(o) {
    if (!o || !o.grunge) return null;
    const amount = grAmount(o);
    if (amount === NEUTRAL) return null;
    return { amount, texture: grTexture(o) };
  }
  function setGrunge(o, patch) {
    const next = { amount: grAmount(o), texture: grTexture(o) };
    if (patch.amount !== undefined) next.amount = patch.amount;
    if (patch.texture !== undefined) next.texture = patch.texture;
    if (next.amount === NEUTRAL) delete o.grunge;          // neutral → drop
    else o.grunge = { amount: next.amount, texture: next.texture };
  }

  // ── GEOMETRY ──────────────────────────────────────────────────────────
  // Deterministic per-object jitter: two images side by side must not wear
  // the exact same dirt. Seeded from obj.id, so it's stable across saves.
  function hash32(str) {
    let h = 2166136261;
    for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 16777619); }
    return h >>> 0;
  }
  function jitter(id) {
    const h = hash32(String(id));
    return {
      zoom: 1.12 + ((h & 0xff) / 255) * 0.26,        // 1.12–1.38× beyond cover
      fx: ((h >>> 8) & 0xffff) / 65535,              // horizontal crop offset
      fy: ((h >>> 20) & 0xfff) / 4095,               // vertical crop offset
    };
  }
  // Cover-fit + zoom + offset. Display expresses this in %, export in px —
  // same numbers either way, which is what keeps the two paths identical.
  function coverFit(id, tex, w, h) {
    const j = jitter(id);
    const s = Math.max(w / tex.w, h / tex.h) * j.zoom;
    return { sw: tex.w * s, sh: tex.h * s, fx: j.fx, fy: j.fy };
  }

  // ── DISPLAY ───────────────────────────────────────────────────────────
  function applyGrunge(obj, el) {
    const host = el || ctx.worldEl.querySelector(`.canvas-obj[data-id="${obj.id}"]`);
    if (!host) return;
    let ov = host.querySelector(':scope > .imgg-ov');
    const g = gr(obj);
    if (!g) {                       // neutral → tear the overlay back out
      if (ov) ov.remove();
      host.style.isolation = '';
      return;
    }
    if (!ov) {
      ov = document.createElement('div');
      ov.className = 'imgg-ov';
      host.appendChild(ov);
    }
    host.style.isolation = 'isolate';   // keep the blend inside this object

    const tex = TEX_BY_ID[g.texture];
    const w = Math.max(1, obj.w), h = Math.max(1, obj.h);
    const f = coverFit(obj.id, tex, w, h);
    const lighten = g.amount < NEUTRAL;

    ov.style.backgroundImage = `url("${tex.url}")`;
    ov.style.backgroundSize = `${(f.sw / w * 100).toFixed(3)}% ${(f.sh / h * 100).toFixed(3)}%`;
    ov.style.backgroundPosition = `${(f.fx * 100).toFixed(2)}% ${(f.fy * 100).toFixed(2)}%`;
    ov.style.mixBlendMode = lighten ? 'screen' : 'multiply';
    ov.style.filter = lighten ? 'invert(1)' : '';
    ov.style.opacity = (Math.abs(g.amount - NEUTRAL) / NEUTRAL).toFixed(4);

    // Clip to the image's own alpha so cut-outs don't wear a dirty
    // rectangle. Opaque photos mask to themselves, i.e. a no-op.
    const im = host.querySelector('img');
    const msk = im && im.getAttribute('src') ? `url("${im.getAttribute('src')}")` : 'none';
    ov.style.webkitMaskImage = msk;
    ov.style.maskImage = msk;
  }

  // ── EXPORT ────────────────────────────────────────────────────────────
  // Same maths on a canvas. Runs in onAfterObjectExport so it lands on top
  // of whatever images/images.filters already painted.
  function drawGrungeExport(c2d, obj, t, imgEl) {
    const g = gr(obj);
    if (!g) return;
    const tex = TEX_BY_ID[g.texture];
    const src = texImg[g.texture];
    if (!src || !src.complete || !src.naturalWidth) return;

    const dw = obj.w * t.scaleX, dh = obj.h * t.scaleY;
    const W = Math.max(1, Math.ceil(dw)), H = Math.max(1, Math.ceil(dh));
    const off = document.createElement('canvas');
    off.width = W; off.height = H;
    const o = off.getContext('2d');

    const f = coverFit(obj.id, tex, W, H);
    o.drawImage(src, -(f.sw - W) * f.fx, -(f.sh - H) * f.fy, f.sw, f.sh);

    const lighten = g.amount < NEUTRAL;
    if (lighten) {
      // Exactly CSS invert(1): difference against white flips every channel.
      o.globalCompositeOperation = 'difference';
      o.fillStyle = '#ffffff';
      o.fillRect(0, 0, W, H);
      o.globalCompositeOperation = 'source-over';
    }
    // Mask to the image's alpha (the canvas twin of the CSS mask above)
    if (imgEl && imgEl.complete && imgEl.naturalWidth) {
      o.globalCompositeOperation = 'destination-in';
      try {
        const c = obj.crop;
        if (c) {
          o.drawImage(imgEl,
            (c.x / 100) * imgEl.naturalWidth, (c.y / 100) * imgEl.naturalHeight,
            (c.w / 100) * imgEl.naturalWidth, (c.h / 100) * imgEl.naturalHeight,
            0, 0, W, H);
        } else {
          o.drawImage(imgEl, 0, 0, W, H);
        }
      } catch (_) { /* decode/cross-origin: fall through unmasked */ }
      o.globalCompositeOperation = 'source-over';
    }

    c2d.save();
    c2d.globalAlpha = Math.abs(g.amount - NEUTRAL) / NEUTRAL;
    c2d.globalCompositeOperation = lighten ? 'screen' : 'multiply';
    c2d.drawImage(off, t.x, t.y, dw, dh);
    c2d.restore();
  }

  // ── MENU PLUMBING ─────────────────────────────────────────────────────
  let grungeUndoTimer = null;
  const menuRefs = { slider: null, val: null, swatches: null };

  function selectedImages() {
    return [...ctx.selectedIds].map(id => ctx.findObject(id)).filter(o => o && o.type === 'image');
  }
  function modeLabel(v) {
    if (v === NEUTRAL) return 'Clean';
    const pct = Math.round(Math.abs(v - NEUTRAL) / NEUTRAL * 100);
    return (v < NEUTRAL ? 'Screen ' : 'Multiply ') + pct + '%';
  }
  function updateVal(v) {
    if (menuRefs.val && menuRefs.val.isConnected) menuRefs.val.textContent = modeLabel(v);
  }
  function markSwatch(texId) {
    if (!menuRefs.swatches || !menuRefs.swatches.isConnected) return;
    for (const b of menuRefs.swatches.querySelectorAll('.imgg-sw')) {
      b.classList.toggle('is-on', b.dataset.tex === texId);
    }
  }

  // Live slider → every selected image; undo coalesced per drag.
  function onGrungeSlider(amount) {
    const imgs = selectedImages();
    if (imgs.length === 0) return;
    if (!grungeUndoTimer) ctx.pushUndo();
    clearTimeout(grungeUndoTimer);
    grungeUndoTimer = setTimeout(() => { grungeUndoTimer = null; }, 600);
    for (const o of imgs) { setGrunge(o, { amount }); applyGrunge(o); }
    updateVal(amount);
    ctx.markDirty();
  }

  function onPickTexture(texId) {
    if (!TEX_BY_ID[texId]) return;
    lastTexture = texId;
    markSwatch(texId);
    const imgs = selectedImages().filter(o => gr(o));   // only live grunge
    if (imgs.length === 0) return;
    grungeUndoTimer = null;                             // close any drag group
    ctx.pushUndo();
    for (const o of imgs) { setGrunge(o, { texture: texId }); applyGrunge(o); }
    ctx.markDirty();
  }

  function resetGrunge() {
    const imgs = selectedImages();
    if (imgs.some(o => gr(o))) {
      grungeUndoTimer = null;
      ctx.pushUndo();
      for (const o of imgs) { delete o.grunge; applyGrunge(o); }
      ctx.markDirty();
    }
    if (menuRefs.slider && menuRefs.slider.isConnected) menuRefs.slider.value = NEUTRAL;
    updateVal(NEUTRAL);
  }

  return {
    // ── STYLES ── overlay + the rows living inside the Grunge ▶ submenu
    css: `
      .imgg-ov {
        position: absolute; inset: 0; pointer-events: none;
        background-repeat: no-repeat; border-radius: inherit;
        -webkit-mask-size: 100% 100%; mask-size: 100% 100%;
        -webkit-mask-repeat: no-repeat; mask-repeat: no-repeat;
      }
      .imgg-row { padding: 6px 14px 8px; width: 208px; cursor: default; font-family: var(--font-sans); }
      .imgg-head { display: flex; justify-content: space-between; font-size: 12px; color: #bbb; margin-bottom: 5px; }
      .imgg-val { color: #F0C4A0; font-variant-numeric: tabular-nums; }
      .imgg-row input[type=range] {
        width: 100%; height: 4px; -webkit-appearance: none; appearance: none;
        background: linear-gradient(90deg,#444 0 calc(50% - 1px),#777 calc(50% - 1px) calc(50% + 1px),#444 calc(50% + 1px) 100%);
        border-radius: 2px; outline: none; cursor: pointer; accent-color: #F0C4A0;
      }
      .imgg-row input[type=range]::-webkit-slider-thumb {
        -webkit-appearance: none; appearance: none; width: 14px; height: 14px; border-radius: 50%;
        background: #F0C4A0; cursor: pointer; border: none;
      }
      .imgg-ends { display: flex; justify-content: space-between; font-size: 10px; color: #777; margin-top: 4px; letter-spacing: .04em; text-transform: uppercase; }
      .imgg-plates { display: flex; gap: 6px; padding: 8px 14px 4px; width: 208px; box-sizing: content-box; }
      .imgg-sw {
        flex: 1; height: 34px; border-radius: 3px; cursor: pointer;
        background-size: cover; background-position: center;
        border: 1px solid #555; box-sizing: border-box; padding: 0;
        filter: grayscale(1); opacity: .65; transition: opacity .12s;
      }
      .imgg-sw:hover { opacity: .9; }
      .imgg-sw.is-on { border-color: #F0C4A0; opacity: 1; box-shadow: 0 0 0 1px #F0C4A0 inset; }
      .imgg-platelbl { font-size: 10px; color: #777; padding: 0 14px 6px; font-family: var(--font-sans); letter-spacing: .04em; text-transform: uppercase; }
    `,

    // ── MENUS ── "Grunge ▶" on the image's right-click menu, sitting
    // directly under Filters (order 30). Function form so the rows carry
    // the selection's current values each time the menu opens.
    objectMenus: {
      image: (selObjs) => {
        const primary = (selObjs || []).find(o => o.type === 'image');
        if (!primary) return [];
        const amount = grAmount(primary);
        const texId = grTexture(primary);
        return [
          {
            label: 'Grunge',
            icon: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><rect x="3" y="3" width="18" height="18" rx="2"/><path d="M7 8h.01M11 6h.01M15 9h.01M9 12h.01M17 13h.01M6 16h.01M12 17h.01M16 18h.01"/></svg>',
            order: 31,
            submenu: [
              {
                html: '<div class="imgg-platelbl">Plate</div>' +
                  '<div class="imgg-plates">' +
                  TEXTURES.map(t =>
                    `<button class="imgg-sw" data-tex="${t.id}" title="${t.label}" style="background-image:url(&quot;${t.thumb}&quot;)"></button>`
                  ).join('') +
                  '</div>',
                onMount(el) {
                  menuRefs.swatches = el;
                  markSwatch(texId);
                },
                onClick(e) {
                  const b = e.target.closest('.imgg-sw');
                  if (b) onPickTexture(b.dataset.tex);
                },
              },
              {
                html:
                  '<div class="imgg-row">' +
                  `<div class="imgg-head"><span>Grunge</span><span class="imgg-val">${modeLabel(amount)}</span></div>` +
                  `<input type="range" min="0" max="100" step="1" value="${amount}">` +
                  '<div class="imgg-ends"><span>Screen</span><span>Multiply</span></div>' +
                  '</div>',
                onMount(el) {
                  const inp = el.querySelector('input');
                  menuRefs.slider = inp;
                  menuRefs.val = el.querySelector('.imgg-val');
                  inp.addEventListener('input', () => onGrungeSlider(+inp.value));
                  inp.addEventListener('dblclick', () => { inp.value = NEUTRAL; onGrungeSlider(NEUTRAL); });
                },
              },
              { divider: true },
              { label: 'Reset Grunge', action() { resetGrunge(); } },
            ],
          },
        ];
      },
    },

    // ── DECORATORS ── paint the overlay wherever images appear
    onObjectRender(obj, el) {
      if (obj.type !== 'image') return;
      applyGrunge(obj, el);
    },
    onAfterObjectExport(c2d, obj, t, ctx) {
      if (obj.type !== 'image' || !gr(obj)) return;
      const imgEl = ctx.worldEl.querySelector(`.canvas-obj[data-id="${obj.id}"] img`);
      try { drawGrungeExport(c2d, obj, t, imgEl); } catch (_) { /* leave the image clean */ }
    },

    // Sanitize our own field on load (never touches obj.filters)
    onReady(ctx) {
      for (const o of ctx.objects) {
        if (o.type !== 'image' || !o.grunge) continue;
        const g = gr(o);
        if (!g) delete o.grunge; else o.grunge = g;
        applyGrunge(o);
      }
    },
  };
}
